import React from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/UserPages.css";

const plans = [
  {
    title: "Free",
    price: "$0/month",
    features: [
      "✅ Post up to 5 listings",
      "✅ Chat with buyers & sellers",
      "✅ Access your dashboard",
    ],
  },
  {
    title: "Pro Seller",
    price: "$9.99/month",
    features: [
      "🚀 Unlimited listings",
      "📊 Sales analytics & performance chart",
      "⭐ Boosted visibility & rating badge",
      "📍 Location-based priority",
    ],
  },
  {
    title: "Gym Vendor",
    price: "$29.99/month",
    features: [
      "🏋️‍♂️ Bulk uploads with CSV",
      "🏆 Verified Vendor Badge",
      "💬 Priority customer support",
      "🧾 Custom business profile page",
    ],
  },
];

const BusinessPlans = () => {
  return (
    <div>
      <Navbar />
      <div className="page-wrapper">
        <h2 className="page-title">💼 ReGym Business Plans</h2>
        <p className="page-subtitle">Choose a plan that fits your hustle.</p>

        <div className="plans-grid">
          {plans.map((plan) => (
            <div className="plan-card" key={plan.title}>
              <h3>{plan.title}</h3>
              <p className="plan-price">{plan.price}</p>
              <ul>
                {plan.features.map((feature, index) => (
                  <li key={index}>{feature}</li>
                ))}
              </ul>
              <button className="subscribe-btn">Choose Plan</button>
            </div>
          ))}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default BusinessPlans;
